import{_ as e,o,c as r,a4 as t}from"./chunks/framework.BybBnFXO.js";const m=JSON.parse('{"title":"GemAtlas 顶级珠宝工坊画廊设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh/superpowers/specs/2026-08-31-maison-gallery-design.md","filePath":"zh/superpowers/specs/2026-08-31-maison-gallery-design.md","lastUpdated":1788135225000}'),s={name:"zh/superpowers/specs/2026-08-31-maison-gallery-design.md"};function n(l,a,d,i,p,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="gematlas-顶级珠宝工坊画廊设计" tabindex="-1">GemAtlas 顶级珠宝工坊画廊设计 <a class="header-anchor" href="#gematlas-顶级珠宝工坊画廊设计" aria-label="Permalink to &quot;GemAtlas 顶级珠宝工坊画廊设计&quot;">​</a></h1><p><strong>日期</strong>：2026-08-31 <strong>状态</strong>：设计已确认，已进入内容检索与实现阶段。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>将现有以文字为主的“顶级珠宝工坊”页面升级为可浏览、可追溯、可持续扩展的高级珠宝作品档案。首期纳入 Cartier、Van Cleef &amp; Arpels、Boucheron、Tiffany &amp; Co.、Harry Winston、Graff、Chaumet 七家工坊，每家选取三件作品，共 21 件。</p><p>首期不创建 21 个独立详情页，而是在现有 <code>by-house</code> 页面中按工坊分组展示，以减少空页面、导航复杂度和维护成本。</p><h2 id="选品规则" tabindex="-1">选品规则 <a class="header-anchor" href="#选品规则" aria-label="Permalink to &quot;选品规则&quot;">​</a></h2><p>每家工坊固定配置三类作品：历史代表作、招牌工艺作、宝石主角作。作品名称、年代、宝石信息和来源逐项核对；不能以搜索摘要或二手营销文案作为唯一依据。</p><h2 id="数据与页面" tabindex="-1">数据与页面 <a class="header-anchor" href="#数据与页面" aria-label="Permalink to &quot;数据与页面&quot;">​</a></h2><p>新增 <code>data/shared/maison-works.yaml</code>，与主题型 <code>gallery.yaml</code> 分离。数据包含双语名称、作品类型、年代、宝石、工艺、风格、双语摘要、资料来源、图片来源和授权状态。生成脚本将双语数据渲染为一页式档案：顶部索引、工坊分区、三列作品卡，以及移动端单列布局。</p><p>作品卡完整展示关键信息，不依赖悬停，不使用自动轮播。图片授权明确时展示本地图片；授权不明确时展示可追溯的外部资料卡，不复制品牌官网图片。</p><h2 id="图片与版权边界" tabindex="-1">图片与版权边界 <a class="header-anchor" href="#图片与版权边界" aria-label="Permalink to &quot;图片与版权边界&quot;">​</a></h2><p>图片优先使用博物馆开放资源、Wikimedia Commons 明确授权素材或公共领域历史图。每张本地图片均记录文件页、作者、许可证、处理方式和语义边界，并同步维护英中文授权清单。作品资料来源与图片授权来源分开记录。</p><h2 id="验证与后续" tabindex="-1">验证与后续 <a class="header-anchor" href="#验证与后续" aria-label="Permalink to &quot;验证与后续&quot;">​</a></h2><p>实现后运行 <code>pnpm generate:pages</code>、<code>pnpm validate:data</code>、<code>pnpm test</code> 和 <code>pnpm build</code>。校验覆盖七家工坊各三件作品、ID 唯一、双语页面数量一致、本地图片存在以及现有站点回归。</p><p>首期稳定后，再考虑按工坊、宝石、工艺和时代增加交叉浏览；当某件作品资料达到足够深度时，再拆分为独立详情页。首期不引入数据库、CMS、自动抓取或复杂筛选器。</p>',15)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
